// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testFuzz_property(uint256 burnAmount) public {
        vm.assume(burnAmount > 0);
        uint256 initialSupply = 1000 ether;
        vm.assume(burnAmount <= initialSupply);

        vm.prank(address(this));
        c.mintToken(address(this), initialSupply);

        uint256 ownerBalanceBefore = c.balanceOf(address(this));
        uint256 totalSupplyBefore = c.totalSupply();

        vm.prank(address(this));
        c.burn(burnAmount);

        uint256 ownerBalanceAfter = c.balanceOf(address(this));
        uint256 totalSupplyAfter = c.totalSupply();

        uint256 balanceDecrease = ownerBalanceBefore - ownerBalanceAfter;
        uint256 supplyDecrease = totalSupplyBefore - totalSupplyAfter;

        assertTrue(balanceDecrease == supplyDecrease);
    }
}
